@Test
    void staticModifiersEmitSetProperty() {
        FrameOpcodeSink sink = new FrameOpcodeSink();
        Emitter emitter = new Emitter(sink);
        View root = View.text("Hi")
                .padding(16)
                .color(Color.RED)
                .background(Color.BLUE)
                .fontSize(20f)
                .fontWeight(FontWeight.BOLD)
                .border(2f, Color.GREEN, 4f)
                .visible(false)
                .frame(100f, 50f, Alignment.CENTER);
        emitter.mount(root, Environment.DEFAULT);

        Frame frame = sink.frame();
        java.util.Set<Integer> properties = new java.util.HashSet<>();
        for (Opcode op : frame.opcodes()) {
            if (op.category() == Categories.STYLE && op.command() == Commands.Style.SET_PROPERTY) {
                properties.add(op.b() & 0xFFFF);
            }
        }
        assertTrue(properties.containsAll(java.util.Set.of(
                Properties.PADDING, Properties.COLOR, Properties.BACKGROUND_COLOR,
                Properties.FONT_SIZE, Properties.FONT_WEIGHT, Properties.BORDER_WIDTH,
                Properties.BORDER_COLOR, Properties.BORDER_RADIUS, Properties.VISIBLE,
                Properties.WIDTH, Properties.HEIGHT, Properties.ALIGNMENT)),
                "every static modifier must emit its SET_PROPERTY: " + properties);
    }

