/**
     * Inline CSS for the node's modifier properties + border (empty when none apply).
     * Pure function of the retained properties; edge padding overrides {@code PADDING}.
     */
    private static String styleCss(Node node) {
        StringBuilder css = new StringBuilder(borderStyle(node));

        Float padding = node.f32(Properties.PADDING);
        Float padTop = node.f32(Properties.PADDING_TOP);
        Float padRight = node.f32(Properties.PADDING_RIGHT);
        Float padBottom = node.f32(Properties.PADDING_BOTTOM);
        Float padLeft = node.f32(Properties.PADDING_LEFT);
        if (padding != null || padTop != null || padRight != null || padBottom != null || padLeft != null) {
            float top = padTop != null ? padTop : padding;
            float right = padRight != null ? padRight : padding;
            float bottom = padBottom != null ? padBottom : padding;
            float left = padLeft != null ? padLeft : padding;
            css.append("padding-top:").append(fmt(top)).append("px;");
            css.append("padding-right:").append(fmt(right)).append("px;");
            css.append("padding-bottom:").append(fmt(bottom)).append("px;");
            css.append("padding-left:").append(fmt(left)).append("px;");
        }

        Integer color = node.color(Properties.COLOR);
        if (color != null) {
            css.append("color:").append(rgba(color)).append(';');
        }
        Integer background = node.color(Properties.BACKGROUND_COLOR);
        if (background != null) {
            css.append("background-color:").append(rgba(background)).append(';');
        }
        Float fontSize = node.f32(Properties.FONT_SIZE);
        if (fontSize != null) {
            css.append("font-size:").append(fmt(fontSize)).append("px;");
        }
        Float fontWeight = node.f32(Properties.FONT_WEIGHT);
        if (fontWeight != null) {
            css.append("font-weight:").append(cssFontWeight(fontWeight)).append(';');
        }
        Float opacity = node.f32(Properties.OPACITY);
        if (opacity != null) {
            css.append("opacity:").append(fmt(opacity)).append(';');
        }
        Float visible = node.f32(Properties.VISIBLE);
        if (visible != null && visible == 0f) {
            css.append("display:none;");
        }
        Float width = node.f32(Properties.WIDTH);
        if (width != null) {
            if (width == Commands.Size.FILL) {
                css.append("flex-grow:1;");
            } else if (width > 0f) {
                css.append("width:").append(fmt(width)).append("px;");
            }
        }
        Float height = node.f32(Properties.HEIGHT);
        if (height != null) {
            if (height == Commands.Size.FILL) {
                css.append("align-self:stretch;");
            } else if (height > 0f) {
                css.append("height:").append(fmt(height)).append("px;");
            }
        }
        Integer alignment = node.color(Properties.ALIGNMENT);
        if (alignment != null) {
            css.append("align-self:").append(cssAlignment(alignment)).append(';');
        }
        return css.toString();
    }

    /** Map a protocol {@code Alignment} wire value to a CSS flex keyword. */
    private static String cssAlignment(int wire) {
        return switch (wire) {
            case 0 -> "flex-start";  // LEADING
            case 2 -> "flex-end";    // TRAILING
            case 3 -> "stretch";     // FILL
            default -> "center";     // CENTER
        };
    }

    /** Map a protocol {@code FontWeight} wire value to a CSS font-weight. */
    private static String cssFontWeight(float wire) {
        return switch ((int) wire) {
            case 0 -> "300"; // LIGHT
            case 2 -> "500"; // MEDIUM
            case 3 -> "600"; // SEMIBOLD
            case 4 -> "bold"; // BOLD
            default -> "normal"; // REGULAR
        };
    }

    /** Format a float Rust-style ({@code 6.0 → "6"}, {@code 0.5 → "0.5"}). */
    private static String fmt(float v) {
        if (v == Math.floor(v) && !Float.isInfinite(v) && v >= Integer.MIN_VALUE && v <= Integer.MAX_VALUE) {
            return String.valueOf((int) v);
        }
        return String.valueOf(v);
    }

