import { describe, it, expect } from 'vitest';
import { CATEGORY, TREE, STYLE, COMPONENT, PROPERTY, VALUE_TYPE, EVENT } from './protocol';
import { Opcode } from './frame';
import { decodeFrame, encodeBatch, StringSectionWriter } from './decoder';
import { eventRouter, f32Bits, f32FromBits } from './event-encoder';
import { RetainedTree } from './retained-tree';

/** Build a self-contained mount frame: VSTACK(1) → [TEXT(2) "Hello"]. */
function mountFrame(): Uint8Array {
  const strings = new StringSectionWriter();
  const hello = strings.push('Hello');
  return encodeBatch([
    new Opcode(CATEGORY.TREE, TREE.CREATE_NODE, 0, 1, COMPONENT.VSTACK, 0),
    new Opcode(CATEGORY.TREE, TREE.CREATE_NODE, 0, 2, COMPONENT.TEXT, 0),
    new Opcode(CATEGORY.TREE, TREE.INSERT_CHILD, 0, 1, 2, 0xffffffff),
    new Opcode(CATEGORY.STYLE, STYLE.SET_TEXT, 0, 2, hello, 0),
  ], strings.toBytes());
}

describe('protocol constants', () => {
  it('matches the canonical component/property ids', () => {
    expect(COMPONENT.VSTACK).toBe(0x0002);
    expect(COMPONENT.TEXT).toBe(0x0003);
    expect(COMPONENT.BUTTON).toBe(0x0004);
    expect(PROPERTY.PADDING).toBe(0x1011);
    expect(PROPERTY.COLOR).toBe(0x100a);
    expect(VALUE_TYPE.STRING).toBe(0x05);
  });
});

describe('decodeFrame', () => {
  it('round-trips opcodes and the string section', () => {
    const frame = decodeFrame(mountFrame());
    expect(frame.opcodes.length).toBe(4);
    expect(frame.opcodes[0].category).toBe(CATEGORY.TREE);
    expect(frame.opcodes[0].command).toBe(TREE.CREATE_NODE);
    expect(frame.opcodes[0].a).toBe(1);
    expect(frame.opcodes[2].command).toBe(TREE.INSERT_CHILD);
    expect(frame.opcodes[2].a).toBe(1);
    expect(frame.opcodes[2].b).toBe(2);
    expect(frame.stringAt(frame.opcodes[3].b)).toBe('Hello');
  });

  it('rejects a bad magic', () => {
    expect(() => decodeFrame(new Uint8Array(32))).toThrow(/magic/);
  });
});

describe('eventRouter', () => {
  it('encodes pointer-up events', () => {
    const bytes = eventRouter.pointerUp(4);
    const frame = decodeFrame(bytes);
    expect(frame.opcodes.length).toBe(1);
    expect(frame.opcodes[0].category).toBe(CATEGORY.EVENT);
    expect(frame.opcodes[0].command).toBe(EVENT.POINTER_UP);
    expect(frame.opcodes[0].a).toBe(4);
  });

  it('encodes text-changed with the text in the string section', () => {
    const bytes = eventRouter.textChanged(7, 'Ada');
    const frame = decodeFrame(bytes);
    expect(frame.opcodes[0].command).toBe(EVENT.TEXT_CHANGED);
    expect(frame.opcodes[0].a).toBe(7);
    expect(frame.stringAt(frame.opcodes[0].b)).toBe('Ada');
  });

  it('encodes value-changed as f32 bits', () => {
    const bytes = eventRouter.valueChanged(6, 0.75);
    const frame = decodeFrame(bytes);
    expect(frame.opcodes[0].command).toBe(EVENT.VALUE_CHANGED);
    expect(f32FromBits(frame.opcodes[0].b)).toBeCloseTo(0.75);
  });

  it('packs/unpacks f32 bits', () => {
    expect(f32FromBits(f32Bits(1))).toBe(1);
    expect(f32FromBits(f32Bits(0.5))).toBe(0.5);
  });
});

describe('RetainedTree', () => {
  it('applies a mount frame and resolves string properties', () => {
    const tree = new RetainedTree();
    tree.applyFrame(decodeFrame(mountFrame()));

    expect(tree.rootId).toBe(1);
    const root = tree.node(1);
    expect(root?.component).toBe(COMPONENT.VSTACK);
    expect(root?.children()).toEqual([2]);

    const text = tree.node(2);
    expect(text?.component).toBe(COMPONENT.TEXT);
    expect(text?.text()).toBe('Hello');
  });

  it('applies SET_PROPERTY with raw bits and string sections', () => {
    const strings = new StringSectionWriter();
    const prompt = strings.push('Your name');
    const bytes = encodeBatch([
      new Opcode(CATEGORY.TREE, TREE.CREATE_NODE, 0, 1, COMPONENT.TEXT_FIELD, 0),
      new Opcode(CATEGORY.STYLE, STYLE.SET_PROPERTY, 0, 1,
        (VALUE_TYPE.F32 << 16) | PROPERTY.FONT_SIZE, f32Bits(20)),
      new Opcode(CATEGORY.STYLE, STYLE.SET_PROPERTY, 0, 1,
        (VALUE_TYPE.STRING << 16) | PROPERTY.PROMPT, prompt),
    ], strings.toBytes());

    const tree = new RetainedTree();
    tree.applyFrame(decodeFrame(bytes));

    const node = tree.node(1)!;
    expect(node.f32(PROPERTY.FONT_SIZE)).toBe(20);
    expect(node.strings().get(PROPERTY.PROMPT)).toBe('Your name');
  });

  it('supports insert/remove/move child deltas', () => {
    const tree = new RetainedTree();
    tree.applyFrame(decodeFrame(mountFrame()));
    tree.applyFrame(decodeFrame(encodeBatch([
      new Opcode(CATEGORY.TREE, TREE.REMOVE_CHILD, 0, 1, 2, 0),
    ], new Uint8Array())));
    expect(tree.node(1)?.children()).toEqual([]);
  });
});

import { COMPONENT, PROPERTY, SIZE, BORDER_EDGE, ALIGNMENT, FONT_WEIGHT } from '../core/protocol';
import { PathlandNode } from '../core/retained-tree';
import { f32FromBits } from '../core/event-encoder';

/**
 * Pathland → ngui mapping. The renderer is a pure function of the opcode stream:
 * this module decodes the retained node's constraint/style properties into the
 * `@apaq/ngui-elements` view + modifier inputs (design-token driven).
 */

export type NodeKind =
  | 'hstack'
  | 'vstack'
  | 'zstack'
  | 'text'
  | 'button'
  | 'image'
  | 'switch'
  | 'textField'
  | 'spacer'
  | 'scrollView'
  | 'list'
  | 'grid'
  | 'comment'
  | 'checkbox'
  | 'slider'
  | 'unknown';

export function kindOf(node: PathlandNode): NodeKind {
  switch (node.component) {
    case COMPONENT.HSTACK: return 'hstack';
    case COMPONENT.VSTACK: return 'vstack';
    case COMPONENT.TEXT: return 'text';
    case COMPONENT.BUTTON: return 'button';
    case COMPONENT.IMAGE: return 'image';
    case COMPONENT.SWITCH: return 'switch';
    case COMPONENT.TEXT_FIELD: return 'textField';
    case COMPONENT.SPACER: return 'spacer';
    case COMPONENT.SCROLLVIEW: return 'scrollView';
    case COMPONENT.LIST: return 'list';
    case COMPONENT.GRID: return 'grid';
    case COMPONENT.COMMENT: return 'comment';
    case COMPONENT.CHECKBOX: return 'checkbox';
    case COMPONENT.SLIDER: return 'slider';
    default: return 'unknown';
  }
}

/** ngui modifier inputs decoded from a node's properties (see `@apaq/ngui-elements/core`). */
export interface NguiMods {
  padding?: unknown;      // PaddingOptions
  color?: string;
  background?: unknown;   // BackgroundOptions
  border?: unknown;       // BorderOptions
  rounding?: unknown;     // RoundingOptions
  opacity?: number;
  font?: unknown;         // FontOptions
  frame?: unknown;        // FrameOptions
  flex?: unknown;         // FlexOptions
  lineLimit?: number;
}

/** A helper type for the ngui `Alignment` string union. */
export type NguiAlignment =
  | 'topLeading' | 'top' | 'topTrailing'
  | 'leading' | 'center' | 'trailing'
  | 'bottomLeading' | 'bottom' | 'bottomTrailing';

/** Decode all modifier properties into ngui inputs (reads the node's signals). */
export function buildMods(node: PathlandNode): NguiMods {
  const mods: NguiMods = {};

  const padding = buildPadding(node);
  if (padding) {
    mods.padding = { paddingAreas: padding };
  }
  const color = node.color(PROPERTY.COLOR);
  if (color !== undefined) {
    mods.color = argbToRgba(color);
  }
  const background = node.color(PROPERTY.BACKGROUND_COLOR);
  if (background !== undefined) {
    mods.background = { color: argbToRgba(background) };
  }
  const border = buildBorder(node);
  if (border) {
    mods.border = border;
  }
  const radius = node.f32(PROPERTY.BORDER_RADIUS);
  if (radius !== undefined && radius > 0) {
    mods.rounding = { radius };
  }
  const opacity = node.f32(PROPERTY.OPACITY);
  if (opacity !== undefined) {
    mods.opacity = opacity;
  }
  const font = buildFont(node);
  if (font.size || font.weight || font.family) {
    mods.font = font;
  }
  const frame = buildFrame(node);
  if (frame) {
    mods.frame = frame;
  }
  const flex = buildFlex(node);
  if (flex) {
    mods.flex = flex;
  }
  const lineLimit = node.f32(PROPERTY.LINE_LIMIT);
  if (lineLimit !== undefined) {
    mods.lineLimit = lineLimit;
  }
  return mods;
}

/** Stack spacing → ngui `[gap]` (px). */
export function stackGap(node: PathlandNode): number | undefined {
  return node.f32(PROPERTY.SPACING);
}

/** Stack cross-axis alignment → ngui `[alignment]`. */
export function stackAlignment(node: PathlandNode): NguiAlignment | undefined {
  const wire = node.f32(PROPERTY.ALIGNMENT);
  return wire === undefined ? undefined : nguiAlignment(wire);
}

/** Text alignment → ngui `[multilineTextAlignment]`. */
export function textAlignment(node: PathlandNode): NguiAlignment | undefined {
  const wire = node.f32(PROPERTY.TEXT_ALIGNMENT);
  return wire === undefined ? undefined : nguiAlignment(wire);
}

/** Checked state (SELECTED) for toggles/checkboxes. */
export function checked(node: PathlandNode): boolean {
  const bits = node.props().get(PROPERTY.SELECTED);
  return bits !== undefined && bits !== 0;
}

/** Whether the node should be hidden (`VISIBLE = 0`). */
export function hidden(node: PathlandNode): boolean {
  const visible = node.f32(PROPERTY.VISIBLE);
  return visible !== undefined && visible === 0;
}

/** A slider's numeric range (VALUE/MIN_VALUE/MAX_VALUE, defaults 0/0/1). */
export function slider(node: PathlandNode): { value: number; min: number; max: number } {
  const min = node.f32(PROPERTY.MIN_VALUE) ?? 0;
  const max = node.f32(PROPERTY.MAX_VALUE) ?? 1;
  const value = node.f32(PROPERTY.VALUE) ?? min;
  return { value, min, max };
}

function buildPadding(node: PathlandNode): { edge: string; gap: number | string }[] | undefined {
  const uniform = node.f32(PROPERTY.PADDING);
  const top = node.f32(PROPERTY.PADDING_TOP);
  const right = node.f32(PROPERTY.PADDING_RIGHT);
  const bottom = node.f32(PROPERTY.PADDING_BOTTOM);
  const left = node.f32(PROPERTY.PADDING_LEFT);
  if (uniform === undefined && top === undefined && right === undefined
      && bottom === undefined && left === undefined) {
    return undefined;
  }
  const areas: { edge: string; gap: number | string }[] = [];
  if (uniform !== undefined && top === undefined && right === undefined
      && bottom === undefined && left === undefined) {
    areas.push({ edge: 'All', gap: uniform });
    return areas;
  }
  const pushEdge = (edge: string, value: number | undefined) => {
    const gap = value ?? uniform;
    if (gap !== undefined) {
      areas.push({ edge, gap });
    }
  };
  pushEdge('Top', top);
  pushEdge('Right', right);
  pushEdge('Bottom', bottom);
  pushEdge('Left', left);
  return areas;
}

function buildBorder(node: PathlandNode): unknown | undefined {
  const width = node.f32(PROPERTY.BORDER_WIDTH);
  if (width === undefined) {
    return undefined;
  }
  const edgesBits = node.props().get(PROPERTY.BORDER_EDGES) ?? BORDER_EDGE.ALL;
  const colorBits = node.color(PROPERTY.BORDER_COLOR);
  const borderAreas: { side: string; width: number }[] = [];
  if (edgesBits === BORDER_EDGE.ALL) {
    borderAreas.push({ side: 'All', width });
  } else {
    if (edgesBits & BORDER_EDGE.TOP) borderAreas.push({ side: 'Top', width });
    if (edgesBits & BORDER_EDGE.BOTTOM) borderAreas.push({ side: 'Bottom', width });
    if (edgesBits & BORDER_EDGE.LEADING) borderAreas.push({ side: 'Left', width });
    if (edgesBits & BORDER_EDGE.TRAILING) borderAreas.push({ side: 'Right', width });
  }
  return {
    borderAreas,
    ...(colorBits !== undefined ? { color: argbToRgba(colorBits) } : {}),
  };
}

function buildFont(node: PathlandNode): { size?: string; weight?: string; family?: string } {
  const font: { size?: string; weight?: string; family?: string } = {};
  const size = node.f32(PROPERTY.FONT_SIZE);
  if (size !== undefined) {
    font.size = `${size}px`;
  }
  const weight = node.f32(PROPERTY.FONT_WEIGHT);
  if (weight !== undefined) {
    font.weight = cssFontWeight(weight);
  }
  const family = node.strings().get(PROPERTY.FONT_FAMILY);
  if (family) {
    font.family = family;
  }
  return font;
}

function buildFrame(node: PathlandNode): unknown | undefined {
  const width = node.f32(PROPERTY.WIDTH);
  const height = node.f32(PROPERTY.HEIGHT);
  const frame: { width?: string; height?: string } = {};
  if (width !== undefined && width > 0) {
    frame.width = `${width}px`;
  }
  if (height !== undefined && height > 0) {
    frame.height = `${height}px`;
  }
  return frame.width || frame.height ? frame : undefined;
}

function buildFlex(node: PathlandNode): unknown | undefined {
  const width = node.f32(PROPERTY.WIDTH);
  const height = node.f32(PROPERTY.HEIGHT);
  if (width === SIZE.FILL) {
    return { grow: 1 };
  }
  if (height === SIZE.FILL) {
    return { grow: 1, basis: '100%' };
  }
  return undefined;
}

/** Protocol `Alignment` wire value → ngui `Alignment` string. */
export function nguiAlignment(wire: number): NguiAlignment {
  switch (Math.round(wire)) {
    case ALIGNMENT.LEADING: return 'leading';
    case ALIGNMENT.TRAILING: return 'trailing';
    case ALIGNMENT.FILL: return 'center';
    default: return 'center';
  }
}

/** Protocol `FontWeight` wire value → CSS font-weight. */
function cssFontWeight(wire: number): string {
  switch (Math.round(wire)) {
    case FONT_WEIGHT.LIGHT: return '300';
    case FONT_WEIGHT.MEDIUM: return '500';
    case FONT_WEIGHT.SEMIBOLD: return '600';
    case FONT_WEIGHT.BOLD: return 'bold';
    default: return 'normal';
  }
}

/** Format `0xAARRGGBB` as a CSS `rgba(...)` string (alpha in `0..1`). */
export function argbToRgba(argb: number): string {
  const a = (argb >>> 24) & 0xff;
  const r = (argb >>> 16) & 0xff;
  const g = (argb >>> 8) & 0xff;
  const b = argb & 0xff;
  const alpha = (a / 255).toFixed(3);
  return `rgba(${r},${g},${b},${alpha})`;
}

void f32FromBits;

